/// The object `#/components/schemas/CorporationsDetail`.
final class CorporationsDetail {
  /// Creates a [CorporationsDetail].
  const CorporationsDetail({
    this.allianceId,
    this.ceoId,
    this.creatorId,
    this.dateFounded,
    required this.description,
    this.enlistedFactionId,
    required this.friendlyFire,
    required this.homeStationId,
    required this.memberCount,
    required this.name,
    this.palette,
    required this.shares,
    required this.state,
    required this.taxRates,
    required this.ticker,
    required this.type,
    this.url,
    required this.warEligible,
  });

  /// Alliance the corporation is a member of (Player-owned corporation only)
  final int? allianceId;

  /// Corporation's CEO ID
  final int? ceoId;

  /// Corporation's creator ID
  final int? creatorId;

  /// Corporation's founding date
  final DateTime? dateFounded;

  /// Corporation's description
  final String description;

  /// Faction the corporation is enlisted in (Player-owned corporation only)
  final int? enlistedFactionId;

  /// Corporation's friendly fire status
  final EsiEnum<CorporationsDetailFriendlyFire> friendlyFire;

  /// Corporation's home station ID
  final int homeStationId;

  /// Corporation's member count
  final int memberCount;

  /// Corporation's name
  final String name;

  /// Corporation's palette colors (Player-owned corporation only)
  final CorporationsDetailPalette? palette;

  /// Corporation's shares
  final int shares;

  /// Corporation's state
  final EsiEnum<CorporationsDetailState> state;

  /// Corporation's tax rates
  final CorporationsDetailTaxrates taxRates;

  /// Corporation's short name
  final String ticker;

  /// Corporation's type
  final EsiEnum<CorporationsDetailType> type;

  /// Corporation's URL
  final String? url;

  /// Corporation's war eligible
  final bool warEligible;

  /// Reads a [CorporationsDetail] from [json] at [path], or raises
  /// [EsiDecodeException] naming the first mismatch.
  static CorporationsDetail fromJson(Object? json, String path) {
    final object = EsiJson.object(json, path);
    return CorporationsDetail(
      allianceId: EsiJson.optional<int>(
        object,
        'alliance_id',
        path,
        EsiJson.integer,
      ),
      ceoId: EsiJson.optional<int>(object, 'ceo_id', path, EsiJson.integer),
      creatorId: EsiJson.optional<int>(
        object,
        'creator_id',
        path,
        EsiJson.integer,
      ),
      dateFounded: EsiJson.optional<DateTime>(
        object,
        'date_founded',
        path,
        EsiJson.dateTime,
      ),
      description: EsiJson.string(
        EsiJson.required(object, 'description', path),
        '$path.description',
      ),
      enlistedFactionId: EsiJson.optional<int>(
        object,
        'enlisted_faction_id',
        path,
        EsiJson.integer,
      ),
      friendlyFire: EsiJson.enumValue<CorporationsDetailFriendlyFire>(
        EsiJson.required(object, 'friendly_fire', path),
        '$path.friendly_fire',
        CorporationsDetailFriendlyFire.values,
      ),
