        EsiJson.required(object, 'home_station_id', path),
        '$path.home_station_id',
      ),
      memberCount: EsiJson.integer(
        EsiJson.required(object, 'member_count', path),
        '$path.member_count',
      ),
      name: EsiJson.string(
        EsiJson.required(object, 'name', path),
        '$path.name',
